  border-left: 4px solid #f59e0b;
}

.order-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.75rem;
}

.order-card-header h3 {
  font-size: 1.1rem;
  font-weight: 600;
  color: #1e293b;
}

.status-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.25rem 0.5rem;
  border-radius: 9999px;
}

.status-label.fulfilled {
  background-color: #dcfce7;
  color: #15803d;
}

.status-label.pending {
  background-color: #fef3c7;
  color: #b45309;
}

.order-items-list {
  margin-bottom: 1rem;
}

.order-items-list h4 {
  font-size: 0.85rem;
  color: #64748b;
  margin-bottom: 0.25rem;
}

.order-items-list ul {
  list-style-type: none;
  padding-left: 0.5rem;
}

.order-items-list li {
  font-size: 0.9rem;
  color: #334155;
  margin-bottom: 0.25rem;
}

.fulfill-btn {
  background-color: #3b82f6;
  color: white;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 0.375rem;
  font-weight: 600;
  cursor: pointer;
  width: 100%;
  transition: background-color 0.2s;
}

.fulfill-btn:hover {
  background-color: #2563eb;
}

.fulfill-btn:disabled {
  background-color: #94a3b8;
  cursor: not-allowed;
}

/* Alerts List */
.alerts-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-height: 400px;
  overflow-y: auto;
  padding-right: 0.5rem;
}

.alert-item-card {
  display: flex;
  gap: 1rem;
  background-color: #fffbeb;
  border: 1px solid #fef3c7;
  border-left: 4px solid #f59e0b;
  border-radius: 0.375rem;
  padding: 1rem;
}

.alert-icon {
  font-size: 1.25rem;
}

.alert-content {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.alert-message {
  font-size: 0.9rem;
  font-weight: 500;
  color: #92400e;
}

.alert-time {
  font-size: 0.75rem;
  color: #b45309;
}

/* Purchase Orders List */
.purchase-orders-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-height: 400px;
  overflow-y: auto;
  padding-right: 0.5rem;
}

.po-item-card {
  background-color: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 0.375rem;
  padding: 1rem;
}

.po-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.5rem;
  border-bottom: 1px solid #e2e8f0;
  padding-bottom: 0.5rem;
}

.po-id {
  font-weight: 700;
  font-size: 0.85rem;
  color: #64748b;
}

.po-status-badge {
  font-size: 0.7rem;
  font-weight: 700;
  background-color: #e0f2fe;
  color: #0369a1;
  padding: 0.15rem 0.4rem;
  border-radius: 0.25rem;
  text-transform: uppercase;
}

.po-body {
  font-size: 0.9rem;
  color: #334155;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.po-footer {
  margin-top: 0.5rem;
  text-align: right;
}

.po-time {
  font-size: 0.75rem;
  color: #94a3b8;
}

.empty-text {
  color: #94a3b8;
  font-style: italic;
  padding: 1rem;
}

.text-center {
  text-align: center;
}
